using System;using System.Collections;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;
using Cysharp.Threading.Tasks;using MiniFramework.Contracts;using MiniFramework.Runtime;using MiniFramework.Platform;using MiniFramework.Providers.WeChat;using MiniFramework.WeChat.Tests;
using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed class WeChatServiceTests
{
    static OperationContext Wait=>OperationContext.Unlimited();static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
    sealed class Env
    {
        internal readonly ScriptedWeChatApi Api;internal readonly PlatformService Service;internal readonly GameContext Context;internal readonly Scope Scope=new Scope("wx-listeners");
        internal Env(ScriptedWeChatApi api=null){Api=api??new ScriptedWeChatApi();Service=new PlatformService(new WeChatBackend(Api));Context=new GameContext(new[]{new ModuleRegistration("platform",Service.Dependencies,()=>Service,typeof(IPlatformLifecycle),typeof(IPlatformLogin),typeof(IPlatformCapabilities))},Cleanup);}
        internal async UniTask Start(){Check(await Context.StartAsync(Wait));}
        internal IPlatformLoginOperation Capture(){var r=Service.CaptureLogin(new PlatformLoginOptions(true));Assert.IsTrue(r.IsSuccess);return r.Value;}
        internal ScriptedWeChatApi.Request Request=>Api.Requests[Api.Requests.Count-1];
        internal async UniTask Finish(){Api.FailRelease=Api.FailOffShow=Api.FailOffHide=false;Api.SavedInitialize?.Invoke(0);foreach(var r in Api.Requests)r.Complete();await Scope.CloseAsync(Cleanup);var closing=Context.CloseAsync(Wait);for(int i=0;i<6;i++){foreach(var r in Api.Requests)r.Complete();await UniTask.Yield();}var result=await closing;if(!result.IsSuccess)result=await Context.RetryCleanupAsync(Cleanup,Wait);Check(result);Assert.AreEqual(0,Context.RetainedModuleCount);}
    }
    readonly List<Env> envs=new List<Env>();Env New(ScriptedWeChatApi api=null){var e=new Env(api);envs.Add(e);return e;}
    static void Check(Result r)=>Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);
    static async UniTask Frames(int n=5){for(int i=0;i<n;i++)await UniTask.Yield();}
    [UnityTearDown]public IEnumerator TearDown()=>UniTask.ToCoroutine(async()=>{Time.timeScale=1;foreach(var e in envs)await e.Finish();envs.Clear();});
    [UnityTest,NUnit.Framework.Property("platformCaseId","cold_open")]public IEnumerator ContextConstructionIsCold()=>UniTask.ToCoroutine(async()=>{var e=New();Assert.AreEqual(0,e.Api.InitializeCalls);await e.Start();e.Capture();Assert.AreEqual(0,e.Api.CreateCalls);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","native_contract_suite")]public IEnumerator ContextPublishesThreeDomainsExplicitly()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.IsTrue(e.Context.TryGet<IPlatformLogin>(out var login));Assert.AreSame(e.Service,login);Assert.AreEqual(PlatformExecutionMode.Mock,e.Service.Descriptor.Mode);});
    [UnityTest]public IEnumerator InitialUnknownDoesNotInventVisibilityOrAds()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(PlatformVisibility.Unknown,e.Service.Visibility);Assert.AreEqual(CapabilitySupport.Unknown,e.Service.Capabilities.Get(PlatformFeature.RewardedAds).Support);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","credential_not_account")]public IEnumerator LoginReturnsRevocableMockCodeWithoutAccount()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var result=await e.Capture().WaitAsync(Wait);Assert.IsTrue(result.IsSuccess);Assert.AreEqual("synthetic-code",result.Value.ReadAuthorizationCode().Value);Assert.AreEqual(PlatformExecutionMode.Mock,result.Value.Mode);await e.Context.CloseAsync(Wait);Assert.IsTrue(result.Value.IsDisposed);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","actual_terminal_fence")]public IEnumerator SuccessRetainsActualAttemptUntilComplete()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.HoldLogin=true;await e.Start();Assert.IsTrue((await e.Capture().WaitAsync(Wait)).IsSuccess);Assert.AreEqual(1,e.Service.ActiveAttemptCount);Assert.AreEqual(0,e.Request.ReleaseCalls);Assert.AreEqual("platform.login.busy",(await e.Capture().WaitAsync(Wait)).Error.Code);e.Request.Complete();await Frames();Assert.AreEqual(0,e.Service.ActiveAttemptCount);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","login_cancel_timeout_late")]public IEnumerator CancellationRetainsWorkAndDiscardsLateCode()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.AutoReply=false;e.Api.HoldLogin=true;await e.Start();using(var c=new CancellationTokenSource()){var t=e.Capture().WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(0,e.Request.ReleaseCalls);e.Request.Success();e.Request.Complete();await Frames();Assert.AreEqual(0,e.Service.HeldCredentialCount);Assert.IsTrue(e.Request.Released);}});
    [UnityTest]public IEnumerator TimeoutDoesNotPretendSdkAbort()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.AutoReply=false;e.Api.HoldLogin=true;await e.Start();Assert.AreEqual(ErrorKind.Timeout,(await e.Capture().WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);Assert.IsFalse(e.Request.ActuallyComplete);e.Request.Complete();await Frames();Assert.IsTrue(e.Request.Released);});
    [UnityTest]public IEnumerator PreCanceledWaitDoesNotConstructSdkRequest()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();using(var c=new CancellationTokenSource()){c.Cancel();await e.Capture().WaitAsync(OperationContext.Unlimited(c.Token));}Assert.AreEqual(0,e.Api.CreateCalls);});
    [UnityTest]public IEnumerator ZeroDeadlineDoesNotCallSdk()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(ErrorKind.Timeout,(await e.Capture().WaitAsync(default)).Error.Kind);Assert.AreEqual(0,e.Api.StartCalls);});
    [UnityTest]public IEnumerator ActualCompleteWithoutResultIsFailure()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.AutoReply=false;await e.Start();var result=await e.Capture().WaitAsync(Wait);Assert.IsFalse(result.IsSuccess);Assert.AreEqual(ErrorKind.Provider,result.Error.Kind);});
    [UnityTest]public IEnumerator DuplicateRawResultsDoNotCreateMoreCredentials()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.HoldLogin=true;await e.Start();var credential=(await e.Capture().WaitAsync(Wait)).Value;e.Request.Success("duplicate");e.Request.Fail();await Frames();Assert.AreEqual(1,e.Service.HeldCredentialCount);Assert.IsFalse(credential.IsDisposed);e.Request.Complete();});
    [UnityTest,NUnit.Framework.Property("platformCaseId","main_thread_callback")]public IEnumerator WorkerCallbacksNotifyOnlyOnMainThread()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var main=Thread.CurrentThread.ManagedThreadId;int called=0,thread=0;e.Service.SubscribeLifecycle(e.Scope,"thread",_=>{called++;thread=Thread.CurrentThread.ManagedThreadId;});var worker=Task.Run(()=>e.Api.Show());while(!worker.IsCompleted)await UniTask.Yield();await Frames();Assert.AreEqual(1,called);Assert.AreEqual(main,thread);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","paused_host_resume")]public IEnumerator PausedTimeScaleStillReceivesShow()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Time.timeScale=0;e.Api.Hide();e.Api.Show();await Frames();Assert.AreEqual(PlatformVisibility.Foreground,e.Service.Visibility);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","lifecycle_sequence")]public IEnumerator DuplicateShowIsDeduplicatedByPlatformService()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();int called=0;e.Service.SubscribeLifecycle(e.Scope,"visibility",_=>called++);e.Api.Show();e.Api.Show();e.Api.Hide();await Frames();Assert.AreEqual(2,called);Assert.AreEqual(PlatformVisibility.Background,e.Service.Visibility);});
    [UnityTest]public IEnumerator StartupSnapshotOrdersEarlierEvents()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.HoldInitialize=true;var start=e.Context.StartAsync(Wait);e.Api.Hide();e.Api.Show();e.Api.SavedInitialize(0);Check(await start);Assert.AreEqual(PlatformVisibility.Foreground,e.Service.Visibility);e.Api.Hide();await Frames();Assert.AreEqual(PlatformVisibility.Background,e.Service.Visibility);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","initialize_success_failure_late")]public IEnumerator CanceledInitializationCannotPublishLateReady()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.HoldInitialize=true;using(var c=new CancellationTokenSource()){var start=e.Context.StartAsync(OperationContext.Unlimited(c.Token));c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await start).Error.Kind);e.Api.SavedInitialize(0);await Frames();Assert.AreNotEqual(PlatformState.Ready,e.Service.State);}});
    [UnityTest]public IEnumerator FailedInitializationRollsBackBindings()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.InitializeCode=4;Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);await Frames();Assert.IsEmpty(e.Api.Shows);Assert.IsEmpty(e.Api.Hides);Assert.AreEqual(0,e.Api.CreateCalls);});
    [UnityTest]public IEnumerator DispatchThrowStaysRetainedUntilRealComplete()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.ThrowStart=true;await e.Start();var result=await e.Capture().WaitAsync(Wait);Assert.AreEqual("wechat.login.dispatch_unknown",result.Error.Code);Assert.AreEqual(1,e.Service.ActiveAttemptCount);e.Request.Complete();await Frames();Assert.AreEqual(0,e.Service.ActiveAttemptCount);Assert.AreEqual(1,e.Api.StartCalls);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","close_unsubscribe")]public IEnumerator CloseWaitsForSdkCompleteThenUnsubscribes()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.HoldLogin=true;await e.Start();await e.Capture().WaitAsync(Wait);var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);Assert.IsNotEmpty(e.Api.Shows);e.Request.Complete();Check(await close);Assert.IsEmpty(e.Api.Shows);Assert.IsTrue(e.Request.Released);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","failed_cleanup_retry")]public IEnumerator ExplicitRetryReleasesWithoutAnotherLogin()=>UniTask.ToCoroutine(async()=>{var e=New();e.Api.FailRelease=true;await e.Start();await e.Capture().WaitAsync(Wait);await Frames();Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);e.Api.FailRelease=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(1,e.Api.StartCalls);Assert.IsTrue(e.Request.Released);});
    [UnityTest]public IEnumerator DetachRetryDoesNotReinitializeSdk()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Api.FailOffHide=true;Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);e.Api.FailOffHide=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(1,e.Api.InitializeCalls);Assert.IsEmpty(e.Api.Hides);});
    [UnityTest,NUnit.Framework.Property("platformCaseId","duplicate_wrong_generation")]public IEnumerator LateOldProducerCannotEnterNewContext()=>UniTask.ToCoroutine(async()=>{var old=New();await old.Start();var stale=old.Api.Shows[0];Check(await old.Context.CloseAsync(Wait));var next=New();await next.Start();int called=0;next.Service.SubscribeLifecycle(next.Scope,"new",_=>called++);stale();await Frames();Assert.AreEqual(0,called);Assert.AreEqual(PlatformVisibility.Unknown,next.Service.Visibility);});
    [UnityTest]public IEnumerator SharedApiUnbindsOnlyItsOwnSessionDelegates()=>UniTask.ToCoroutine(async()=>{var api=new ScriptedWeChatApi();var a=New(api);var b=New(api);await a.Start();await b.Start();Check(await a.Context.CloseAsync(Wait));Assert.AreEqual(1,api.Shows.Count);api.Show();await Frames();Assert.AreEqual(PlatformVisibility.Foreground,b.Service.Visibility);});
    [UnityTest]public IEnumerator ScopeCloseStopsLifecycleListener()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();int called=0;e.Service.SubscribeLifecycle(e.Scope,"scope",_=>called++);await e.Scope.CloseAsync(Cleanup);e.Api.Show();await Frames();Assert.AreEqual(0,called);});
    [UnityTest]public IEnumerator RepeatedContextCyclesLeaveNoBindings()=>UniTask.ToCoroutine(async()=>{for(int i=0;i<5;i++){var e=New();await e.Start();await e.Capture().WaitAsync(Wait);Check(await e.Context.CloseAsync(Wait));Assert.IsEmpty(e.Api.Shows);Assert.IsEmpty(e.Api.Hides);Assert.AreEqual(0,e.Service.ActiveAttemptCount);}});
}
